private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node cannot be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node cannot be null");
    }
    // Create a circulator starting at the given node and direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If the start node is already the stop node, return immediately
    if (start.equals(stop)) {
        return circ;
    }
    // Keep track of the first node to avoid infinite loops
    Node first = circ.current();
    do {
        Node current = circ.current();
        if (predicate.test(current)) {
            return circ;
        }
        if (current.equals(stop)) {
            return circ;
        }
        circ.next();
    } while (!circ.current().equals(first));
    // If we looped back to the start without finding a match, return the circulator
    return circ;
}

