private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    long total = 0L;
    for (int val : bounds) {
        total += val;
    }
    int[] suffixArr = new int[n];
    long running = 0L;
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffixArr[i] = (int) running;
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffixList.add(suffixArr[i]);
    }
    return new Pair<>(suffixList, total);
}

