private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        int b0 = bb.get() & 0xFF;
        int codePoint;
        if (b0 < 0x80) { // 1-byte sequence
            codePoint = b0;
        } else if ((b0 >> 5) == 0x6) { // 2-byte sequence
            int b1 = bb.get() & 0xFF;
            if ((b1 >> 6) != 0x2) throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        } else if ((b0 >> 4) == 0xE) { // 3-byte sequence
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            if ((b1 >> 6) != 0x2 || (b2 >> 6) != 0x2)
                throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        } else if ((b0 >> 3) == 0x1E) { // 4-byte sequence
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            if ((b1 >> 6) != 0x2 || (b2 >> 6) != 0x2 || (b3 >> 6) != 0x2)
                throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 start byte");
        }

        if (codePoint <= 0xFFFF) {
            sb.append((char) codePoint);
        } else {
            // Encode surrogate pair
            codePoint -= 0x10000;
            char high = (char) ((codePoint >> 10) + 0xD800);
            char low = (char) ((codePoint & 0x3FF) + 0xDC00);
            sb.append(high).append(low);
        }
    } catch (BufferUnderflowException e) {
        throw new IllegalArgumentException("Incomplete UTF-8 sequence", e);
    }
    return i + 1;
}

