public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if the path is absolute
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split the path into segments, keeping empty segments if any
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        String segment = part;
        if (decode) {
            try {
                segment = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (Exception e) {
                // If decoding fails, keep the original percent-encoded segment
            }
        }
        segments.add(new PathSegmentImpl(segment));
    }
    return segments;
}

